{
  description = "A Nix-built container sandbox for coding agents";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";

    flake-parts = {
      url = "github:hercules-ci/flake-parts";
      inputs.nixpkgs-lib.follows = "nixpkgs";
    };
  };

  outputs =
    inputs@{ flake-parts, ... }:
    flake-parts.lib.mkFlake { inherit inputs; } {
      systems = [
        "x86_64-linux"
        "aarch64-linux"
      ];

      imports = [
        inputs.flake-parts.flakeModules.partitions
        ./nix/flake/project.nix
      ];

      # Authoring tools stay out of the package and image input graph.
      partitionedAttrs = {
        checks = "dev";
        devShells = "dev";
        formatter = "dev";
      };

      partitions.dev = {
        extraInputsFlake = ./dev;
        module = import ./nix/flake/dev-partition.nix;
      };
    };
}

_: {
  perSystem =
    { pkgs, ... }:
    let
      inherit (pkgs) lib;

      rustSource = lib.fileset.toSource {
        root = ../..;
        fileset = lib.fileset.unions [
          ../../src
          ../../proto
          ../../build.rs
          ../../Cargo.toml
          ../../Cargo.lock
        ];
      };

      agent = pkgs.rustPlatform.buildRustPackage {
        pname = "agent-sandbox";
        version = "0.1.0";
        src = rustSource;
        cargoLock.lockFile = ../../Cargo.lock;
        nativeBuildInputs = [ pkgs.protobuf ];
        nativeCheckInputs = [ pkgs.bubblewrap ];
        strictDeps = true;

        meta = {
          description = "Containerized code sandbox service";
          license = lib.licenses.mit;
          mainProgram = "agent-sandbox";
          platforms = lib.platforms.linux;
        };
      };

      tesseract = pkgs.tesseract.override {
        enableLanguages = [ "eng" ];
      };

      python = pkgs.python3.withPackages (pythonPackages: [
        pythonPackages.matplotlib
        pythonPackages.numpy
        pythonPackages.openpyxl
        pythonPackages.orjson
        pythonPackages.pandas
        pythonPackages.pillow
        ((pythonPackages.pytesseract.override { inherit tesseract; }).overridePythonAttrs (_: {
          doCheck = false;
        }))
        pythonPackages.requests
      ]);

      agentRuntimePackages = [
        agent
        pkgs.bubblewrap
        pkgs.cacert
        tesseract
        python
      ];

      agentRuntime = pkgs.buildEnv {
        name = "agent-sandbox-runtime";
        paths = agentRuntimePackages;
      };

      agentRootfs = pkgs.runCommand "agent-sandbox-rootfs" { } ''
        mkdir -p "$out/dev" "$out/etc" "$out/home/user" "$out/proc" "$out/tmp" "$out/usr/bin" "$out/var/tmp"
        chmod 1777 "$out/tmp" "$out/var/tmp"
        cat > "$out/etc/passwd" <<'EOF'
        root:x:0:0:root:/root:/bin/sh
        sandbox-manager:x:10001:10001:Sandbox manager:/home/user:/bin/sh
        EOF
        cat > "$out/etc/group" <<'EOF'
        root:x:0:
        sandbox-manager:x:10001:
        EOF
        ln -s ${lib.getExe agent} "$out/usr/bin/agent-sandbox"
      '';

      agentImage = pkgs.dockerTools.buildLayeredImage {
        name = "ghcr.io/johnrichardrinehart/agent-sandbox";
        tag = "latest";
        contents = agentRuntimePackages;
        fakeRootCommands = ''
          mkdir -p ./dev ./etc ./home/user ./proc ./tmp ./var/tmp
          chmod 1777 ./tmp ./var/tmp
          cat > ./etc/passwd <<'EOF'
          root:x:0:0:root:/root:/bin/sh
          sandbox-manager:x:10001:10001:Sandbox manager:/home/user:/bin/sh
          EOF
          cat > ./etc/group <<'EOF'
          root:x:0:
          sandbox-manager:x:10001:
          EOF
          chown 10001:10001 ./home/user
        '';
        config = {
          User = "sandbox-manager";
          Env = [
            "HOME=/home/user"
            "AGENT_SANDBOX_BWRAP=${lib.getExe pkgs.bubblewrap}"
            "SSL_CERT_FILE=${pkgs.cacert}/etc/ssl/certs/ca-bundle.crt"
          ];
          WorkingDir = "/home/user";
          Entrypoint = [ (lib.getExe agent) ];
          ExposedPorts."8080/tcp" = { };
          Labels = {
            "org.opencontainers.image.description" = "Containerized code sandbox service";
            "org.opencontainers.image.licenses" = "MIT";
            "org.opencontainers.image.source" = "https://github.com/johnrichardrinehart/agent-sandbox";
            "org.opencontainers.image.title" = "Agent sandbox";
          };
        };
      };

      publishImage = pkgs.writeShellApplication {
        name = "publish-image";
        runtimeInputs = [
          pkgs.coreutils
          pkgs.skopeo
        ];
        text = lib.removePrefix "#!/usr/bin/env nix-shell\n" (
          builtins.readFile ../../scripts/publish-image.sh
        );
      };

      exerciseImage = pkgs.writeShellApplication {
        name = "exercise-agent-image";
        runtimeInputs = [ pkgs.grpcurl ];
        text = lib.removePrefix "#!/usr/bin/env nix-shell\n" (
          builtins.readFile ../../scripts/exercise-image.sh
        );
      };

      nspawnApp = pkgs.writeShellApplication {
        name = "agent-systemd-nspawn";
        runtimeInputs = [ pkgs.systemd ];
        text = ''
          machine="agent-sandbox-$UID"
          command=(
            sudo ${pkgs.systemd}/bin/systemd-nspawn
            --quiet
            --directory=${agentRootfs}
            --volatile=overlay
            --register=no
            --settings=no
            --machine="$machine"
            --bind-ro=/nix/store
            "--tmpfs=/home/user:mode=0750,uid=10001,gid=10001"
            --setenv=HOME=/home/user
            --setenv=AGENT_SANDBOX_LISTEN=0.0.0.0:8080
            --user=sandbox-manager
            /usr/bin/agent-sandbox
          )

          if [[ "''${1:-}" == "--dry-run" ]]; then
            printf '%q ' "''${command[@]}"
            printf '\n'
            exit 0
          fi

          if ! command -v sudo >/dev/null; then
            echo 'agent-systemd-nspawn requires the host sudo wrapper' >&2
            exit 1
          fi

          echo 'Starting an ephemeral systemd-nspawn unit (wheel authorization required).' >&2
          exec "''${command[@]}"
        '';
      };

      clippyCheck = pkgs.rustPlatform.buildRustPackage {
        pname = "agent-sandbox-clippy";
        version = "0.1.0";
        src = rustSource;
        cargoLock.lockFile = ../../Cargo.lock;
        nativeBuildInputs = [
          pkgs.clippy
          pkgs.protobuf
        ];
        strictDeps = true;
        doCheck = false;
        buildPhase = ''
          runHook preBuild
          cargo clippy --all-targets --locked --offline -- -D warnings
          runHook postBuild
        '';
        installPhase = ''
          touch "$out"
        '';
      };

      scriptShebangCheck = pkgs.runCommand "agent-sandbox-script-shebang-check" { } ''
        for script in ${../../scripts}/*.sh; do
          test "$(head -n 1 "$script")" = '#!/usr/bin/env nix-shell'
          grep --fixed-strings --line-regexp '#! nix-shell -i bash' "$script" >/dev/null
        done
        touch "$out"
      '';

      sourcehutManifestCheck =
        pkgs.runCommand "agent-sandbox-sourcehut-manifest-check"
          {
            nativeBuildInputs = [
              pkgs.jq
              pkgs.yq-go
            ];
          }
          ''
            yq --output-format=json '.' ${../../.build.yml} | jq --exit-status '
              .image == "nixos/unstable" and
              .sources == ["git@git.sr.ht:~fuzzybear3965/agent-sandbox"] and
              .secrets == [
                "3a60ba67-89eb-49e6-a818-f4d28848de74",
                "6e416072-c83c-4b52-b040-42396f7d2b74"
              ] and
              (.tasks | length) == 3 and
              .submitter["git.sr.ht"].enabled == true
            ' >/dev/null
            cp ${../../.build.yml} "$out"
          '';

      composeCheck =
        pkgs.runCommand "agent-sandbox-compose-check"
          {
            nativeBuildInputs = [
              pkgs.podman
              pkgs.podman-compose
            ];
          }
          ''
            export HOME="$TMPDIR/home"
            export XDG_RUNTIME_DIR="$TMPDIR/run"
            mkdir -p "$HOME" "$XDG_RUNTIME_DIR"
            podman-compose --file ${../../docker-compose.yaml} config > "$out"
          '';

      # Keep this test as an explicit package rather than a flake check. CI runs
      # `nix flake check`, so it evaluates but does not build the expensive VM.
      nixosVmTest = pkgs.testers.runNixOSTest {
        name = "agent-sandbox-cluster";

        nodes = {
          machine =
            { pkgs, ... }:
            {
              virtualisation = {
                docker.enable = true;
                diskSize = 8192;
                memorySize = 2048;
              };
              environment.systemPackages = [
                pkgs.docker-compose
                pkgs.grpcurl
                pkgs.jq
              ];
            };

          storage =
            { pkgs, ... }:
            {
              systemd.services.seaweedfs = {
                wantedBy = [ "multi-user.target" ];
                after = [ "network.target" ];
                serviceConfig = {
                  DynamicUser = true;
                  StateDirectory = "seaweedfs";
                  ExecStart = "${pkgs.seaweedfs}/bin/weed server -dir=/var/lib/seaweedfs -ip=127.0.0.1 -ip.bind=0.0.0.0 -master.port=19333 -volume.port=18080 -filer -filer.port=18888 -s3 -s3.port=9000";
                };
              };
              networking.firewall.allowedTCPPorts = [ 9000 ];
              environment.systemPackages = [ pkgs.curl ];
            };
        };

        testScript = ''
          start_all()
          machine.wait_for_unit("docker.service")
          storage.wait_for_unit("seaweedfs.service")
          storage.wait_until_succeeds(
              "curl --fail --silent http://127.0.0.1:9000 >/dev/null"
          )
          storage.succeed(
              "curl --fail --silent --request PUT "
              "http://127.0.0.1:9000/agent-sandbox"
          )
          storage.succeed("printf startup-sync >/tmp/from-s3.txt")
          storage.succeed(
              "curl --fail --silent --request PUT "
              "--data-binary @/tmp/from-s3.txt "
              "http://127.0.0.1:9000/agent-sandbox/home/from-s3.txt"
          )
          machine.succeed("docker load < ${agentImage}")
          machine.fail(
              "docker run --rm --network none "
              "--env AGENT_SANDBOX_S3_BUCKET=missing "
              "--env AGENT_SANDBOX_S3_ENDPOINT=http://127.0.0.1:1 "
              "--env AWS_DEFAULT_REGION=us-east-1 "
              "--env AWS_SKIP_SIGNATURE=true "
              "ghcr.io/johnrichardrinehart/agent-sandbox:latest"
          )

          storage_ip = storage.succeed(
              "ip -4 -o address show dev eth1 | awk '{print $4}' | cut -d/ -f1"
          ).strip()
          compose_env = (
              "AGENT_SANDBOX_S3_BUCKET=agent-sandbox "
              "AGENT_SANDBOX_SECCOMP_PROFILE=${../../seccomp.json} "
              f"AGENT_SANDBOX_S3_ENDPOINT=http://{storage_ip}:9000 "
              "AGENT_SANDBOX_S3_PREFIX=home "
              "AWS_DEFAULT_REGION=us-east-1 AWS_ALLOW_HTTP=true "
              "AWS_SKIP_SIGNATURE=true "
          )
          compose = (
              compose_env
              + "docker-compose --project-name agent-sandbox "
              + "--file ${../../docker-compose.yaml} "
          )
          machine.succeed(compose + "up --detach --no-build")
          machine.wait_until_succeeds(
              "grpcurl -plaintext 127.0.0.1:8080 list "
              "sandbox.v0.FilesystemService | grep WriteFile"
          )
          machine.succeed(
              "grpcurl -plaintext -d "
              "'{\"service\":\"sandbox.v0.FilesystemService\"}' "
              "127.0.0.1:8080 grpc.health.v1.Health/Check "
              "| grep SERVING"
          )
          machine.succeed(
              "grpcurl -plaintext -d "
              "'{\"service\":\"sandbox.v0.CommandService\"}' "
              "127.0.0.1:8080 grpc.health.v1.Health/Check "
              "| grep SERVING"
          )
          machine.succeed(
              "test \"$(docker ps --filter status=running --format '{{.Names}}' | wc -l)\" -eq 1"
          )

          def write_file(source, destination):
              machine.succeed(
                  f"payload=$(base64 -w0 {source}); "
                  f"request=$(jq -nc --arg path '{destination}' --arg content \"$payload\" "
                  "'{path:$path,content:$content,createParents:true}'); "
                  "grpcurl -plaintext -d \"$request\" 127.0.0.1:8080 "
                  "sandbox.v0.FilesystemService/WriteFile >/dev/null"
              )
              machine.succeed(
                  f"request=$(jq -nc --arg path '{destination}' '{{path:$path}}'); "
                  "grpcurl -plaintext -d \"$request\" 127.0.0.1:8080 "
                  "sandbox.v0.FilesystemService/ReadFile "
                  f"| jq -r .content | base64 -d | cmp - {source}"
              )

          def execute_script(script, expected, stream="stdout"):
              machine.succeed(
                  f"request=$(jq -nc --arg script '{script}' "
                  "'{argv:[\"python\",$script],timeoutMs:\"120000\"}'); "
                  "grpcurl -plaintext -d \"$request\" 127.0.0.1:8080 "
                  "sandbox.v0.CommandService/ExecuteCommand >/tmp/command.json; "
                  "code=$(jq -r '.exitCode // 0' /tmp/command.json); "
                  "if [ \"$code\" -ne 0 ]; then "
                  "jq -r .stderr /tmp/command.json | base64 -d >&2; exit \"$code\"; fi; "
                  f"jq -r .{stream} /tmp/command.json | base64 -d | grep -F '{expected}'"
              )

          machine.succeed(
              "grpcurl -plaintext -d '{\"path\":\"from-s3.txt\"}' "
              "127.0.0.1:8080 sandbox.v0.FilesystemService/ReadFile "
              "| jq -r .content | base64 -d | grep -Fx startup-sync"
          )
          machine.fail(
              "grpcurl -plaintext -d "
              "'{\"path\":\"../escape.txt\",\"content\":\"\"}' "
              "127.0.0.1:8080 sandbox.v0.FilesystemService/WriteFile"
          )

          write_file("${../../csv_transform.py}", "csv_transform.py")
          write_file("${../../linked_list.py}", "linked_list.py")
          write_file("${../../ocr_demo.py}", "ocr_demo.py")
          execute_script("csv_transform.py", "wrote summary.csv")
          execute_script("linked_list.py", "OK", "stderr")
          execute_script("ocr_demo.py", "OCR round trip OK")

          machine.succeed(
              "code=\"import sys; print('bad', file=sys.stderr); raise SystemExit(7)\"; "
              "request=$(jq -nc --arg code \"$code\" "
              "'{argv:[\"python\",\"-c\",$code]}'); "
              "grpcurl -plaintext -d \"$request\" 127.0.0.1:8080 "
              "sandbox.v0.CommandService/ExecuteCommand >/tmp/failure.json; "
              "test \"$(jq -r .exitCode /tmp/failure.json)\" -eq 7; "
              "jq -r .stderr /tmp/failure.json | base64 -d | grep -Fx bad"
          )
          machine.succeed(
              "request=$(jq -nc --arg command "
              "'open(\"/tmp/leak\", \"w\").write(\"leak\")' "
              "'{argv:[\"python\",\"-c\",$command]}'); "
              "grpcurl -plaintext -d \"$request\" 127.0.0.1:8080 "
              "sandbox.v0.CommandService/ExecuteCommand >/tmp/transient.json; "
              "code=$(jq -r '.exitCode // 0' /tmp/transient.json); "
              "if [ \"$code\" -ne 0 ]; then "
              "jq -r .stderr /tmp/transient.json | base64 -d >&2; exit \"$code\"; fi"
          )
          machine.succeed(
              "request=$(jq -nc --arg command "
              "'import os,sys; sys.exit(os.path.exists(\"/tmp/leak\"))' "
              "'{argv:[\"python\",\"-c\",$command]}'); "
              "grpcurl -plaintext -d \"$request\" 127.0.0.1:8080 "
              "sandbox.v0.CommandService/ExecuteCommand | jq -e '(.exitCode // 0) == 0'"
          )
          machine.succeed(
              "request=$(jq -nc --arg command "
              "'import os,time; pid=os.fork(); "
              "pid and os._exit(0); os.setsid(); "
              "fd=os.open(\"/dev/null\",os.O_RDWR); "
              "[os.dup2(fd,n) for n in (0,1,2)]; "
              "time.sleep(1); open(\"descendant-leak\",\"w\").close()' "
              "'{argv:[\"python\",\"-c\",$command]}'); "
              "grpcurl -plaintext -d \"$request\" 127.0.0.1:8080 "
              "sandbox.v0.CommandService/ExecuteCommand | jq -e '(.exitCode // 0) == 0'; "
              "sleep 2"
          )
          machine.fail(
              "grpcurl -plaintext -d '{\"path\":\"descendant-leak\"}' "
              "127.0.0.1:8080 sandbox.v0.FilesystemService/ReadFile"
          )
          machine.succeed(
              "grpcurl -plaintext -d '{\"argv\":[\"missing-executable\"]}' "
              "127.0.0.1:8080 sandbox.v0.CommandService/ExecuteCommand "
              "| jq -e '(.exitCode // 0) != 0 and ((.stderr // \"\") | length > 0)'"
          )
          machine.succeed(
              "grpcurl -plaintext -d "
              "'{\"argv\":[\"python\",\"-c\",\"import time; time.sleep(10)\"],\"timeoutMs\":\"10\"}' "
              "127.0.0.1:8080 sandbox.v0.CommandService/ExecuteCommand "
              "| jq -e '.exitCode == 124 and ((.stderr | @base64d) == \"command timed out\\n\")'"
          )
          machine.succeed(
              "request=$(jq -nc --arg command "
              "'import os; os.symlink(\"/tmp/escaped\", \"dangling\")' "
              "'{argv:[\"python\",\"-c\",$command]}'); "
              "grpcurl -plaintext -d \"$request\" 127.0.0.1:8080 "
              "sandbox.v0.CommandService/ExecuteCommand | jq -e '(.exitCode // 0) == 0'"
          )
          machine.fail(
              "grpcurl -plaintext -d "
              "'{\"path\":\"dangling\",\"content\":\"ZXNjYXBl\"}' "
              "127.0.0.1:8080 sandbox.v0.FilesystemService/WriteFile"
          )

          machine.succeed(
              "request=$(jq -nc --arg path persisted.txt --arg content cGVyc2lzdGVk "
              "'{path:$path,content:$content}'); "
              "grpcurl -plaintext -d \"$request\" 127.0.0.1:8080 "
              "sandbox.v0.FilesystemService/WriteFile >/dev/null"
          )
          machine.succeed(compose + "down")
          storage.wait_until_succeeds(
              "test \"$(curl --fail --silent "
              "http://127.0.0.1:9000/agent-sandbox/home/persisted.txt)\" "
              "= persisted"
          )
          machine.succeed(compose + "up --detach --no-build")
          machine.wait_until_succeeds(
              "grpcurl -plaintext -d '{\"path\":\"persisted.txt\"}' "
              "127.0.0.1:8080 sandbox.v0.FilesystemService/ReadFile "
              "| jq -r .content | base64 -d | grep -Fx persisted"
          )
        '';
      };
    in
    {
      packages = {
        default = agent;
        agent-sandbox = agent;
        agent-image = agentImage;
        oci-image = agentImage;
        agent-rootfs = agentRootfs;
        agent-runtime = agentRuntime;
        agent-systemd-nspawn = nspawnApp;
        exercise-image = exerciseImage;
        publish-image = publishImage;
        nixos-vm-test = nixosVmTest;
      };

      apps = {
        agent-systemd-nspawn = {
          program = lib.getExe nspawnApp;
          meta.description = "Run agent-sandbox in an ephemeral systemd-nspawn unit";
        };
        exercise-image = {
          program = lib.getExe exerciseImage;
          meta.description = "Exercise a running agent sandbox OCI image";
        };
        publish-image = {
          program = lib.getExe publishImage;
          meta.description = "Publish and verify the agent sandbox OCI image";
        };
      };

      # Consumer outputs are mirrored into the development partition's checks.
      # This keeps `nix flake check` authoritative without putting authoring
      # inputs in the image or package closure.
      _module.args.agentSandboxChecks = {
        inherit
          agentImage
          agentRootfs
          clippyCheck
          composeCheck
          exerciseImage
          nspawnApp
          publishImage
          scriptShebangCheck
          sourcehutManifestCheck
          ;
        agentPackage = agent;
      };
    };
}

FROM nixos/nix:2.35.1

ENV NIX_CONFIG="experimental-features = nix-command flakes"
WORKDIR /build
COPY . .
RUN mkdir -p /opt /home/user \
    && nix build --out-link /opt/agent-runtime .#agent-runtime \
    && printf '%s\n' \
      'sandbox-manager:x:10001:10001:Sandbox manager:/home/user:/bin/sh' \
      >>/etc/passwd \
    && printf '%s\n' 'sandbox-manager:x:10001:' >>/etc/group \
    && chown 10001:10001 /home/user \
    && find /build -mindepth 1 -delete \
    && nix store gc

USER sandbox-manager
ENV HOME=/home/user
ENV PATH=/opt/agent-runtime/bin:/nix/var/nix/profiles/default/bin
ENV SSL_CERT_FILE=/opt/agent-runtime/etc/ssl/certs/ca-bundle.crt
WORKDIR /home/user
EXPOSE 8080
HEALTHCHECK --interval=5s --timeout=3s --retries=5 \
  CMD ["python", "-c", "import socket; socket.create_connection(('127.0.0.1', 8080), timeout=2).close()"]
ENTRYPOINT ["/opt/agent-runtime/bin/agent-sandbox"]

--- compose ---
services:
  agent:
    build:
      context: .
    image: ghcr.io/johnrichardrinehart/agent-sandbox:latest
    environment:
      AGENT_SANDBOX_LISTEN: 0.0.0.0:8080
      AGENT_SANDBOX_S3_BUCKET: ${AGENT_SANDBOX_S3_BUCKET:-}
      AGENT_SANDBOX_S3_ENDPOINT: ${AGENT_SANDBOX_S3_ENDPOINT:-}
      AGENT_SANDBOX_S3_PREFIX: ${AGENT_SANDBOX_S3_PREFIX:-home}
      AWS_ACCESS_KEY_ID: ${AWS_ACCESS_KEY_ID:-}
      AWS_ALLOW_HTTP: ${AWS_ALLOW_HTTP:-false}
      AWS_DEFAULT_REGION: ${AWS_DEFAULT_REGION:-us-east-1}
      AWS_SECRET_ACCESS_KEY: ${AWS_SECRET_ACCESS_KEY:-}
      AWS_SKIP_SIGNATURE: ${AWS_SKIP_SIGNATURE:-false}
    extra_hosts:
      - "host.docker.internal:host-gateway"
    ports:
      - "8080:8080"
    restart: unless-stopped
    stop_grace_period: 30s
    healthcheck:
      test:
        - CMD
        - python
        - -c
        - "import socket; socket.create_connection(('127.0.0.1', 8080), timeout=2).close()"
      interval: 5s
      timeout: 3s
      retries: 5
      start_period: 2s

--- project ---
_: {
  perSystem =
    { pkgs, ... }:
    let
      inherit (pkgs) lib;

      rustSource = lib.fileset.toSource {
        root = ../..;
        fileset = lib.fileset.unions [
          ../../src
          ../../proto
          ../../build.rs
          ../../Cargo.toml
          ../../Cargo.lock
        ];
      };

      agent = pkgs.rustPlatform.buildRustPackage {
        pname = "agent-sandbox";
        version = "0.1.0";
        src = rustSource;
        cargoLock.lockFile = ../../Cargo.lock;
        nativeBuildInputs = [ pkgs.protobuf ];
        strictDeps = true;

        meta = {
          description = "Containerized code sandbox service";
          license = lib.licenses.mit;
          mainProgram = "agent-sandbox";
          platforms = lib.platforms.linux;
        };
      };

      python = pkgs.python3.withPackages (pythonPackages: [
        pythonPackages.matplotlib
        pythonPackages.numpy
        pythonPackages.openpyxl
        pythonPackages.orjson
        pythonPackages.pandas
        pythonPackages.pillow
        pythonPackages.pytesseract
        pythonPackages.requests
      ]);

      agentRuntimePackages = [
        agent
        pkgs.cacert
        pkgs.tesseract
        python
      ];

      agentRuntime = pkgs.buildEnv {
        name = "agent-sandbox-runtime";
        paths = agentRuntimePackages;
      };

      agentRootfs = pkgs.runCommand "agent-sandbox-rootfs" { } ''
        mkdir -p "$out/etc" "$out/home/user" "$out/usr/bin"
        cat > "$out/etc/passwd" <<'EOF'
        root:x:0:0:root:/root:/bin/sh
        sandbox-manager:x:10001:10001:Sandbox manager:/home/user:/bin/sh
        EOF
        cat > "$out/etc/group" <<'EOF'
        root:x:0:
        sandbox-manager:x:10001:
        EOF
        ln -s ${lib.getExe agent} "$out/usr/bin/agent-sandbox"
      '';

      agentImage = pkgs.dockerTools.buildLayeredImage {
        name = "ghcr.io/johnrichardrinehart/agent-sandbox";
        tag = "latest";
        contents = agentRuntimePackages;
        fakeRootCommands = ''
          mkdir -p ./etc ./home/user
          cat > ./etc/passwd <<'EOF'
          root:x:0:0:root:/root:/bin/sh
          sandbox-manager:x:10001:10001:Sandbox manager:/home/user:/bin/sh
          EOF
          cat > ./etc/group <<'EOF'
          root:x:0:
          sandbox-manager:x:10001:
          EOF
          chown 10001:10001 ./home/user
        '';
        config = {
          User = "sandbox-manager";
          Env = [
            "HOME=/home/user"
            "SSL_CERT_FILE=${pkgs.cacert}/etc/ssl/certs/ca-bundle.crt"
          ];
          WorkingDir = "/home/user";
          Entrypoint = [ (lib.getExe agent) ];
          ExposedPorts."8080/tcp" = { };
          Labels = {
            "org.opencontainers.image.description" = "Containerized code sandbox service";
            "org.opencontainers.image.licenses" = "MIT";
            "org.opencontainers.image.source" = "https://github.com/johnrichardrinehart/agent-sandbox";
            "org.opencontainers.image.title" = "Agent sandbox";
          };
        };
      };

      publishImage = pkgs.writeShellApplication {
        name = "publish-image";
        runtimeInputs = [
          pkgs.coreutils
          pkgs.skopeo
        ];
        text = lib.removePrefix "#!/usr/bin/env nix-shell\n" (
          builtins.readFile ../../scripts/publish-image.sh
        );
      };

      exerciseImage = pkgs.writeShellApplication {
        name = "exercise-agent-image";
        runtimeInputs = [ pkgs.grpcurl ];
        text = lib.removePrefix "#!/usr/bin/env nix-shell\n" (
          builtins.readFile ../../scripts/exercise-image.sh
        );
      };

      nspawnApp = pkgs.writeShellApplication {
        name = "agent-systemd-nspawn";
        runtimeInputs = [ pkgs.systemd ];
        text = ''
          machine="agent-sandbox-$UID"
          command=(
            sudo ${pkgs.systemd}/bin/systemd-nspawn
            --quiet
            --directory=${agentRootfs}
            --volatile=overlay
            --register=no
            --settings=no
            --machine="$machine"
            --bind-ro=/nix/store
            "--tmpfs=/home/user:mode=0750,uid=10001,gid=10001"
            --setenv=HOME=/home/user
            --setenv=AGENT_SANDBOX_LISTEN=0.0.0.0:8080
            --user=sandbox-manager
            /usr/bin/agent-sandbox
          )

          if [[ "''${1:-}" == "--dry-run" ]]; then
            printf '%q ' "''${command[@]}"
            printf '\n'
            exit 0
          fi

          if ! command -v sudo >/dev/null; then
            echo 'agent-systemd-nspawn requires the host sudo wrapper' >&2
            exit 1
          fi

          echo 'Starting an ephemeral systemd-nspawn unit (wheel authorization required).' >&2
          exec "''${command[@]}"
        '';
      };

      clippyCheck = pkgs.rustPlatform.buildRustPackage {
        pname = "agent-sandbox-clippy";
        version = "0.1.0";
        src = rustSource;
        cargoLock.lockFile = ../../Cargo.lock;
        nativeBuildInputs = [
          pkgs.clippy
          pkgs.protobuf
        ];
        strictDeps = true;
        doCheck = false;
        buildPhase = ''
          runHook preBuild
          cargo clippy --all-targets --locked --offline -- -D warnings
          runHook postBuild
        '';
        installPhase = ''
          touch "$out"
        '';
      };

      scriptShebangCheck = pkgs.runCommand "agent-sandbox-script-shebang-check" { } ''
        for script in ${../../scripts}/*.sh; do
          test "$(head -n 1 "$script")" = '#!/usr/bin/env nix-shell'
          grep --fixed-strings --line-regexp '#! nix-shell -i bash' "$script" >/dev/null
        done
        touch "$out"
      '';

      sourcehutManifestCheck =
        pkgs.runCommand "agent-sandbox-sourcehut-manifest-check"
          {
            nativeBuildInputs = [
              pkgs.jq
              pkgs.yq-go
            ];
          }
          ''
            yq --output-format=json '.' ${../../.build.yml} | jq --exit-status '
              .image == "nixos/unstable" and
              .sources == ["git@git.sr.ht:~fuzzybear3965/agent-sandbox"] and
              .secrets == [
                "3a60ba67-89eb-49e6-a818-f4d28848de74",
                "6e416072-c83c-4b52-b040-42396f7d2b74"
              ] and
              (.tasks | length) == 3 and
              .submitter["git.sr.ht"].enabled == true
            ' >/dev/null
            cp ${../../.build.yml} "$out"
          '';

      composeCheck =
        pkgs.runCommand "agent-sandbox-compose-check"
          {
            nativeBuildInputs = [
              pkgs.podman
              pkgs.podman-compose
            ];
          }
          ''
            export HOME="$TMPDIR/home"
            export XDG_RUNTIME_DIR="$TMPDIR/run"
            mkdir -p "$HOME" "$XDG_RUNTIME_DIR"
            podman-compose --file ${../../docker-compose.yaml} config > "$out"
          '';

      # Keep this test as an explicit package rather than a flake check. CI runs
      # `nix flake check`, so it evaluates but does not build the expensive VM.
      nixosVmTest = pkgs.testers.runNixOSTest {
        name = "agent-sandbox-cluster";

        nodes = {
          machine =
            { pkgs, ... }:
            {
              virtualisation = {
                docker.enable = true;
                diskSize = 8192;
                memorySize = 2048;
              };
              environment.systemPackages = [
                pkgs.docker-compose
                pkgs.grpcurl
                pkgs.jq
              ];
            };

          storage =
            { pkgs, ... }:
            {
              systemd.services.seaweedfs = {
                wantedBy = [ "multi-user.target" ];
                after = [ "network.target" ];
                serviceConfig = {
                  DynamicUser = true;
                  StateDirectory = "seaweedfs";
                  ExecStart = "${pkgs.seaweedfs}/bin/weed server -dir=/var/lib/seaweedfs -ip=127.0.0.1 -ip.bind=0.0.0.0 -master.port=19333 -volume.port=18080 -filer -filer.port=18888 -s3 -s3.port=9000";
                };
              };
              networking.firewall.allowedTCPPorts = [ 9000 ];
              environment.systemPackages = [ pkgs.curl ];
            };
        };

        testScript = ''
          start_all()
          machine.wait_for_unit("docker.service")
          storage.wait_for_unit("seaweedfs.service")
          storage.wait_until_succeeds(
              "curl --fail --silent http://127.0.0.1:9000 >/dev/null"
          )
          storage.succeed(
              "curl --fail --silent --request PUT "
              "http://127.0.0.1:9000/agent-sandbox"
          )
          storage.succeed("printf startup-sync >/tmp/from-s3.txt")
          storage.succeed(
              "curl --fail --silent --request PUT "
              "--data-binary @/tmp/from-s3.txt "
              "http://127.0.0.1:9000/agent-sandbox/home/from-s3.txt"
          )
          machine.succeed("docker load < ${agentImage}")

          storage_ip = storage.succeed(
              "ip -4 -o address show dev eth1 | awk '{print $4}' | cut -d/ -f1"
          ).strip()
          compose_env = (
              "AGENT_SANDBOX_S3_BUCKET=agent-sandbox "
              f"AGENT_SANDBOX_S3_ENDPOINT=http://{storage_ip}:9000 "
              "AGENT_SANDBOX_S3_PREFIX=home "
              "AWS_DEFAULT_REGION=us-east-1 AWS_ALLOW_HTTP=true "
              "AWS_SKIP_SIGNATURE=true "
          )
          compose = (
              compose_env
              + "docker-compose --project-name agent-sandbox "
              + "--file ${../../docker-compose.yaml} "
          )
          machine.succeed(compose + "up --detach --no-build")
          machine.wait_until_succeeds(
              "grpcurl -plaintext 127.0.0.1:8080 list "
              "sandbox.v0.FilesystemService | grep WriteFile"
          )
          machine.succeed(
              "grpcurl -plaintext -d "
              "'{\"service\":\"sandbox.v0.FilesystemService\"}' "
              "127.0.0.1:8080 grpc.health.v1.Health/Check "
              "| grep SERVING"
          )
          machine.succeed(
              "grpcurl -plaintext -d "
              "'{\"service\":\"sandbox.v0.CommandService\"}' "
              "127.0.0.1:8080 grpc.health.v1.Health/Check "
              "| grep SERVING"
          )
          machine.succeed(
              "test \"$(docker ps --filter status=running --format '{{.Names}}' | wc -l)\" -eq 1"
          )

          def write_file(source, destination):
              machine.succeed(
                  f"payload=$(base64 -w0 {source}); "
                  f"request=$(jq -nc --arg path '{destination}' --arg content \"$payload\" "
                  "'{path:$path,content:$content,createParents:true}'); "
                  "grpcurl -plaintext -d \"$request\" 127.0.0.1:8080 "
                  "sandbox.v0.FilesystemService/WriteFile >/dev/null"
              )
              machine.succeed(
                  f"request=$(jq -nc --arg path '{destination}' '{{path:$path}}'); "
                  "grpcurl -plaintext -d \"$request\" 127.0.0.1:8080 "
                  "sandbox.v0.FilesystemService/ReadFile "
                  f"| jq -r .content | base64 -d | cmp - {source}"
              )

          def execute_script(script, expected, stream="stdout"):
              machine.succeed(
                  f"request=$(jq -nc --arg script '{script}' "
                  "'{argv:[\"python\",$script],timeoutMs:\"120000\"}'); "
                  "grpcurl -plaintext -d \"$request\" 127.0.0.1:8080 "
                  "sandbox.v0.CommandService/ExecuteCommand >/tmp/command.json; "
                  "test \"$(jq -r '.exitCode // 0' /tmp/command.json)\" -eq 0; "
                  f"jq -r .{stream} /tmp/command.json | base64 -d | grep -F '{expected}'"
              )

          machine.succeed(
              "grpcurl -plaintext -d '{\"path\":\"from-s3.txt\"}' "
              "127.0.0.1:8080 sandbox.v0.FilesystemService/ReadFile "
              "| jq -r .content | base64 -d | grep -Fx startup-sync"
          )
          machine.fail(
              "grpcurl -plaintext -d "
              "'{\"path\":\"../escape.txt\",\"content\":\"\"}' "
              "127.0.0.1:8080 sandbox.v0.FilesystemService/WriteFile"
          )

          write_file("${../../csv_transform.py}", "csv_transform.py")
          write_file("${../../linked_list.py}", "linked_list.py")
          write_file("${../../ocr_demo.py}", "ocr_demo.py")
          execute_script("csv_transform.py", "wrote summary.csv")
          execute_script("linked_list.py", "OK", "stderr")
          execute_script("ocr_demo.py", "OCR round trip OK")

          machine.succeed(
              "code=\"import sys; print('bad', file=sys.stderr); raise SystemExit(7)\"; "
              "request=$(jq -nc --arg code \"$code\" "
              "'{argv:[\"python\",\"-c\",$code]}'); "
              "grpcurl -plaintext -d \"$request\" 127.0.0.1:8080 "
              "sandbox.v0.CommandService/ExecuteCommand >/tmp/failure.json; "
              "test \"$(jq -r .exitCode /tmp/failure.json)\" -eq 7; "
              "jq -r .stderr /tmp/failure.json | base64 -d | grep -Fx bad"
          )

          machine.succeed(
              "request=$(jq -nc --arg path persisted.txt --arg content cGVyc2lzdGVk "
              "'{path:$path,content:$content}'); "
              "grpcurl -plaintext -d \"$request\" 127.0.0.1:8080 "
              "sandbox.v0.FilesystemService/WriteFile >/dev/null"
          )
          machine.succeed(compose + "down")
          storage.wait_until_succeeds(
              "test \"$(curl --fail --silent "
              "http://127.0.0.1:9000/agent-sandbox/home/persisted.txt)\" "
              "= persisted"
          )
          machine.succeed(compose + "up --detach --no-build")
          machine.wait_until_succeeds(
              "grpcurl -plaintext -d '{\"path\":\"persisted.txt\"}' "
              "127.0.0.1:8080 sandbox.v0.FilesystemService/ReadFile "
              "| jq -r .content | base64 -d | grep -Fx persisted"
          )
        '';
      };
    in
    {
      packages = {
        default = agent;
        agent-sandbox = agent;
        agent-image = agentImage;
        oci-image = agentImage;
        agent-rootfs = agentRootfs;
        agent-runtime = agentRuntime;
        agent-systemd-nspawn = nspawnApp;
        exercise-image = exerciseImage;
        publish-image = publishImage;
        nixos-vm-test = nixosVmTest;
      };

      apps = {
        agent-systemd-nspawn = {
          program = lib.getExe nspawnApp;
          meta.description = "Run agent-sandbox in an ephemeral systemd-nspawn unit";
        };
        exercise-image = {
          program = lib.getExe exerciseImage;
          meta.description = "Exercise a running agent sandbox OCI image";
        };
        publish-image = {
          program = lib.getExe publishImage;
          meta.description = "Publish and verify the agent sandbox OCI image";
        };
      };

      # Consumer outputs are mirrored into the development partition's checks.
      # This keeps `nix flake check` authoritative without putting authoring
      # inputs in the image or package closure.
      _module.args.agentSandboxChecks = {
        inherit
          agentImage
          agentRootfs
          clippyCheck
          composeCheck
          exerciseImage
          nspawnApp
          publishImage
          scriptShebangCheck
          sourcehutManifestCheck
          ;
        agentPackage = agent;
      };
    };
}

{
  description = "Agent sandbox development-only inputs";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";

    git-hooks = {
      url = "github:cachix/git-hooks.nix";
      inputs.nixpkgs.follows = "nixpkgs";
    };

    treefmt-nix = {
      url = "github:numtide/treefmt-nix";
      inputs.nixpkgs.follows = "nixpkgs";
    };
  };

  outputs = _: { };
}

{ inputs, ... }:
{
  imports = [
    inputs.git-hooks.flakeModule
    inputs.treefmt-nix.flakeModule
  ];

  perSystem =
    {
      agentSandboxChecks,
      config,
      pkgs,
      ...
    }:
    let
      runDockerDaemon = pkgs.writeShellApplication {
        name = "agent-dockerd-runner";
        runtimeInputs = [
          pkgs.coreutils
          pkgs.docker
          pkgs.iproute2
        ];
        text = ''
          owner_pid=$1
          watch_cwd=$2
          project_root=$3
          project_id=$4
          uid="''${SUDO_UID:?agent-dockerd-runner must run through sudo}"
          gid="''${SUDO_GID:?agent-dockerd-runner must run through sudo}"
          runtime_dir="/run/user/$uid"
          daemon_dir="$runtime_dir/agent-sandbox-docker-$project_id"
          pidfile="$daemon_dir/dockerd.pid"
          bridge="asd-''${project_id:0:11}"
          network_id=$(printf '%s' "$project_root" | cksum | cut -d ' ' -f1)
          bridge_second=$((64 + network_id % 64))
          bridge_third=$((network_id / 64 % 256))
          bridge_address="10.$bridge_second.$bridge_third.1/24"
          bridge_cidr="10.$bridge_second.$bridge_third.0/24"

          [[ "$owner_pid" =~ ^[1-9][0-9]*$ ]] || exit 1
          [[ "$watch_cwd" == 0 || "$watch_cwd" == 1 ]] || exit 1
          [[ "$project_root" == /* && -d "$project_root" ]] || exit 1
          [[ "$project_id" =~ ^[A-Za-z0-9_.-]{1,40}$ ]] || exit 1
          [[ "$project_id" != . && "$project_id" != .. ]] || exit 1

          cleanup() {
            if [[ -n "''${daemon_pid:-}" ]]; then
              kill "$daemon_pid" 2>/dev/null || true
              wait "$daemon_pid" 2>/dev/null || true
            fi
            ip link delete "$bridge" 2>/dev/null || true
            rm -rf "$daemon_dir"
          }
          trap cleanup EXIT INT TERM

          if [[ -f "$daemon_dir/runner.pid" ]]; then
            previous_runner=$(<"$daemon_dir/runner.pid")
            previous_command=$(tr '\0' ' ' <"/proc/$previous_runner/cmdline" 2>/dev/null || true)
            if [[ "$previous_runner" =~ ^[1-9][0-9]*$ \
              && "$previous_command" == *agent-dockerd-runner*" $project_id"* ]]; then
              kill "$previous_runner" 2>/dev/null || true
              for _ in $(seq 1 50); do
                kill -0 "$previous_runner" 2>/dev/null || break
                sleep 0.1
              done
            fi
          fi

          if [[ -f "$pidfile" ]]; then
            previous_daemon=$(<"$pidfile")
            previous_command=$(tr '\0' ' ' <"/proc/$previous_daemon/cmdline" 2>/dev/null || true)
            if [[ "$previous_daemon" =~ ^[1-9][0-9]*$ \
              && "$previous_command" == *dockerd*"--data-root $daemon_dir/data"* ]]; then
              kill "$previous_daemon" 2>/dev/null || true
              for _ in $(seq 1 50); do
                kill -0 "$previous_daemon" 2>/dev/null || break
                sleep 0.1
              done
            fi
          fi

          ip link delete "$bridge" 2>/dev/null || true
          rm -rf "$daemon_dir"
          install -d -m 0750 -o root -g "$gid" "$daemon_dir"
          printf '%s\n' "$$" >"$daemon_dir/runner.pid"
          printf '%s\n' "$owner_pid" >"$daemon_dir/owner.pid"

          ip link add name "$bridge" type bridge
          ip address add "$bridge_address" dev "$bridge"
          ip link set "$bridge" up

          dockerd \
            --bridge "$bridge" \
            --fixed-cidr "$bridge_cidr" \
            --data-root "$daemon_dir/data" \
            --exec-root "$daemon_dir/exec" \
            --group "$gid" \
            --host "unix://$daemon_dir/docker.sock" \
            --pidfile "$pidfile" &
          daemon_pid=$!

          while kill -0 "$owner_pid" 2>/dev/null && kill -0 "$daemon_pid" 2>/dev/null; do
            if [[ "$watch_cwd" == 1 ]]; then
              owner_cwd=$(readlink -f "/proc/$owner_pid/cwd" 2>/dev/null || true)
              [[ "$owner_cwd" == "$project_root" || "$owner_cwd" == "$project_root/"* ]] || break
            fi
            sleep 1
          done
        '';
      };

      startDockerDaemon = pkgs.writeShellApplication {
        name = "agent-docker-daemon";
        runtimeInputs = [
          pkgs.coreutils
          pkgs.docker-client
        ];
        text = ''
          owner_pid=$1
          watch_cwd=$2
          project_root=$(readlink -f "$3")
          project_name=$(basename "$project_root")
          project_id=$(printf '%s' "$project_name" | tr -c 'A-Za-z0-9_.-' '-' | cut -c1-40)
          [[ "$project_id" != . && "$project_id" != .. ]] || project_id=worktree
          uid=$(id -u)
          daemon_dir="/run/user/$uid/agent-sandbox-docker-$project_id"
          socket="$daemon_dir/docker.sock"
          log="/run/user/$uid/agent-sandbox-dockerd-$project_id.log"
          docker_host="unix://$socket"

          [[ "$owner_pid" =~ ^[1-9][0-9]*$ ]] || {
            echo 'Docker daemon owner PID must be a positive integer.' >&2
            exit 1
          }
          [[ "$watch_cwd" == 0 || "$watch_cwd" == 1 ]] || {
            echo 'Docker daemon cwd monitoring must be 0 or 1.' >&2
            exit 1
          }
          [[ "$project_root" == /* && -d "$project_root" ]] || {
            echo 'Docker daemon project root must be an existing directory.' >&2
            exit 1
          }

          if [[ -S "$socket" \
            && -f "$daemon_dir/owner.pid" \
            && "$(<"$daemon_dir/owner.pid")" == "$owner_pid" ]] \
            && docker --host "$docker_host" info >/dev/null 2>&1; then
            exit 0
          fi

          if [[ " $(id -Gn) " != *" wheel "* ]]; then
            echo 'The ephemeral Docker daemon requires membership in the wheel group.' >&2
            exit 1
          fi
          if ! command -v sudo >/dev/null; then
            echo 'The ephemeral Docker daemon requires the host sudo wrapper.' >&2
            exit 1
          fi

          echo 'Authorizing the ephemeral Docker daemon for this development shell.' >&2
          sudo -v

          : >"$log"

          # Close inherited file descriptors before sudo starts the runner.
          # Long-lived processes can keep direnv's internal pipes open.
          ${pkgs.bash}/bin/bash -c '
            exec </dev/null >"$1" 2>&1
            for fd_path in /proc/$$/fd/*; do
              fd="''${fd_path##*/}"
              [[ "$fd" =~ ^[0-9]+$ && "$fd" -ge 3 ]] || continue
              eval "exec $fd>&-"
            done
            exec sudo --non-interactive --background "$2" \
              "$3" "$4" "$5" "$6"
          ' _ "$log" ${runDockerDaemon}/bin/agent-dockerd-runner \
            "$owner_pid" "$watch_cwd" "$project_root" "$project_id"

          for _ in $(seq 1 100); do
            if [[ -S "$socket" ]] && docker --host "$docker_host" info >/dev/null 2>&1; then
              exit 0
            fi
            sleep 0.1
          done

          echo "Docker's socket did not become ready at $socket" >&2
          tail -n 20 "$log" >&2
          exit 1
        '';
      };
    in
    {
      treefmt = {
        projectRootFile = "flake.nix";
        flakeCheck = false;
        programs = {
          actionlint.enable = true;
          deadnix.enable = true;
          nixfmt.enable = true;
          prettier.enable = true;
          rustfmt.enable = true;
          shellcheck.enable = true;
          shfmt.enable = true;
          statix.enable = true;
          taplo.enable = true;
        };
        settings.formatter = {
          # The challenge specification and acceptance scripts are fixtures.
          prettier.excludes = [ "INSTRUCTIONS.md" ];
          shellcheck.includes = [
            "*.sh"
            ".envrc"
          ];
          shfmt.includes = [
            "*.sh"
            ".envrc"
          ];
        };
      };

      pre-commit.settings.hooks = {
        treefmt.enable = true;
        check-added-large-files.enable = true;
        check-merge-conflicts.enable = true;

        flake-check-before-push = {
          enable = true;
          name = "authoritative Nix checks";
          entry = "${pkgs.nix}/bin/nix flake check --print-build-logs";
          always_run = true;
          pass_filenames = false;
          require_serial = true;
          stages = [ "pre-push" ];
        };
      };

      checks = {
        agent-sandbox = agentSandboxChecks.agentPackage;
        agent-image = agentSandboxChecks.agentImage;
        agent-rootfs = agentSandboxChecks.agentRootfs;
        agent-systemd-nspawn = agentSandboxChecks.nspawnApp;
        cargo-clippy = agentSandboxChecks.clippyCheck;
        compose = agentSandboxChecks.composeCheck;
        docker-detachment = pkgs.runCommand "agent-sandbox-docker-detachment-check" { } ''
          daemon=${startDockerDaemon}/bin/agent-docker-daemon
          grep --fixed-strings 'for fd_path in /proc/$$/fd/*' "$daemon" >/dev/null
          grep --fixed-strings 'exec sudo --non-interactive --background' "$daemon" >/dev/null
          grep --fixed-strings 'sudo -v' "$daemon" >/dev/null
          touch "$out"
        '';
        exercise-image = agentSandboxChecks.exerciseImage;
        publish-image = agentSandboxChecks.publishImage;
        script-shebangs = agentSandboxChecks.scriptShebangCheck;
        sourcehut-manifest = agentSandboxChecks.sourcehutManifestCheck;
      };

      devShells.default = pkgs.mkShell {
        packages = [
          startDockerDaemon
          pkgs.cargo
          pkgs.clippy
          pkgs.docker-client
          pkgs.nixd
          pkgs.podman
          pkgs.podman-compose
          pkgs.protobuf
          pkgs.rustc
          pkgs.rustfmt
        ];
        shellHook = ''
          ${config.pre-commit.installationScript}
          export XDG_RUNTIME_DIR="''${XDG_RUNTIME_DIR:-/run/user/$(id -u)}"
          docker_owner_pid="''${AGENT_SANDBOX_DIRENV_OWNER_PID:-$$}"
          docker_watch_cwd="''${AGENT_SANDBOX_DIRENV_ACTIVE:-0}"
          docker_project_root=$(readlink -f "''${AGENT_SANDBOX_PROJECT_ROOT:-$PWD}")
          docker_project_name=$(basename "$docker_project_root")
          docker_project_id=$(printf '%s' "$docker_project_name" | tr -c 'A-Za-z0-9_.-' '-' | cut -c1-40)
          [[ "$docker_project_id" != . && "$docker_project_id" != .. ]] || docker_project_id=worktree
          export DOCKER_SOCK="$XDG_RUNTIME_DIR/agent-sandbox-docker-$docker_project_id/docker.sock"
          export DOCKER_HOST="unix://$DOCKER_SOCK"

          if [[ -z "''${CI:-}" \
            && "''${AGENT_SANDBOX_DIRENV_ACTIVE:-}" != 1 \
            && "''${AGENT_SANDBOX_SKIP_DOCKER_DAEMON:-}" != 1 ]]; then
            agent-docker-daemon \
              "$docker_owner_pid" "$docker_watch_cwd" "$docker_project_root"
          fi
        '';
      };
    };
}
